ALL = CASES + PROBES + NEW + V3


def _hard(rep):
    return [f for f in rep.findings if f.severity == "hard"]


def _caught(rep, expected):
    return any(f.code == code and (not sub or sub.lower() in f.title.lower())
               for f in _hard(rep) for code, sub in expected)


@pytest.mark.parametrize("mode", ["edit", "rewrite"])
@pytest.mark.parametrize("case", ALL, ids=[c[0] for c in ALL])
def test_injected_error_caught_and_control_clean(case, mode):
    cid, what, expected, src, ok, bad = case
    if cid in NEEDS_MORPH and not tk.has_morph():
        pytest.skip("нужен pymorphy3")
    if mode not in ONLY_MODES.get(cid, (mode,)):
        pytest.skip(f"{cid} проверяется только в режимах {ONLY_MODES[cid]}")
    ctrl = check.run(ok, src, mode, "claude", "post")
    assert _hard(ctrl) == [], f"{cid} контроль: ложная тревога {[f.title for f in _hard(ctrl)]}"
    rep = check.run(bad, src, mode, "claude", "post")
    assert _caught(rep, expected), f"{cid} ({what}) пропущено; жёсткие: {[f.title for f in _hard(rep)]}"
    assert not rep.passed
